  return MAIN_ITEM_BASE_PREMIUM_PRICE_LIST[item.type] ?? 0;
}''','''// The MHPCO insures only the types on its price list; anything else is refused
// rather than priced.
function listedPriceFor(priceList: Readonly<Record<string, number>>, item: Item): number {
